int copy_xfrm_templates(struct xfrm_policy *xp, struct sk_buff *skb) {
    struct xfrm_user_tmpl *ut;
    struct xfrm_tmpl *tmpl;
    int ntmpls = 0;
    int i;

    if (!xp->num_tmpl)
        return 0;

    for (i = 0; i < xp->num_tmpl; i++) {
        if (!skb_tailroom(skb))
            return -1;

        ut = skb_put(skb, sizeof(*ut));
        memset(ut, 0, sizeof(*ut));

        tmpl = &xp->tmpl[i];
        ut->dir = tmpl->dir;
        ut->mode = tmpl->mode;
        ut->reqid = tmpl->reqid;
        ut->family = tmpl->family;
        ut->saddr = tmpl->saddr;
        ut->id.proto = tmpl->id.proto;
        ut->id.dport = tmpl->id.dport;
        ut->id.sport = tmpl->id.sport;
        ut->id.daddr = tmpl->id.daddr;
        ut->id.proto = tmpl->id.proto;
        ut->sport_mask = tmpl->sport_mask;
        ut->dport_mask = tmpl->dport_mask;
        ut->sprio = tmpl->prio;
    }

    return ntmpls * sizeof(*ut);
}

