}

int copy_templates_to_skb(struct xfrm_policy *xp, struct sk_buff *skb) {
    int bytes_added = 0;
    int i;

    if (!xp->num_tmpl) {
        return 0;
    }

    struct xfrm_user_tmpl *utmpl = kmalloc(xp->num_tmpl * sizeof(*utmpl), GFP_ATOMIC);
    if (!utmpl) {
        return 0;
    }

    for (i = 0; i < xp->num_tmpl; i++) {
        utmpl[i].id = xp->tmpl[i].id;
        utmpl[i].saddr = xp->tmpl[i].saddr;
        utmpl[i].daddr = xp->tmpl[i].daddr;
        utmpl[i].spi = xp->tmpl[i].spi;
        utmpl[i].mode = xp->tmpl[i].mode;
        utmpl[i].reqid = xp->tmpl[i].reqid;
        utmpl[i].family = xp->tmpl[i].family;
        utmpl[i].saddr_all = xp->tmpl[i].saddr_all;
        utmpl[i].daddr_all = xp->tmpl[i].daddr_all;
    }

    bytes_added = nla_put(skb, XFRMA_TMPL, xp->num_tmpl * sizeof(*utmpl), utmpl);

    kfree(utmpl);

    return bytes_added;
}

int copy_templates_to_skb(struct xfrm_policy *xp, struct sk_buff *skb) {
