        struct xfrm_user_tmpl utmpl;

        utmpl = (struct xfrm_user_tmpl) {
            .dir = xp->templates[i].dir,
            .mode = xp->templates[i].mode,
            .reqid = xp->templates[i].reqid,
            .saddr = xp->templates[i].saddr,
            .daddr = xp->templates[i].daddr,
            .sport = xp->templates[i].sport,
            .dport = xp->templates[i].dport,
            .proto = xp->templates[i].proto,
        };

        if (nla_put(skb, XFRMA_TMPL, sizeof(utmpl), &utmpl))
